example.programlisting:
ointerfaces interfaces;
while (!interfaces.End ())
{
	CPLNetworks * networks = new CPLNetworks (interfaces.Interface ().Name ());
	networks->Enumerate ();
	while (!networks->End ())
	{
		networks->Selected ().Enumerate ();
		networks->SelectNext ();
	}
	delete networks;
	interfaces.SelectNext ();
}
